import { Controller, Get, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 연계 명세 제공 전이므로 연계 대상은 규칙에 적힌 네 가지로 한정한다.
const ALLOWED_TARGETS = ['주거래은행 CMS', '카드사', '전자세금계산서', '결의서'];
const DIRECTIONS = ['SEND', 'RECEIVE'];
// 가정: 외부 연동 접속 정보가 없어 연계를 수행하지 못하고 실패로 기록한다.
const NO_CONNECTOR_REASON = '외부 시스템 연동 접속 정보가 설정되지 않아 연계를 수행하지 못했습니다.';

function optionalText(value: unknown, max: number, label: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string' || value.length > max) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 형식이 올바르지 않습니다.');
  }
  return value;
}

@Controller('api/v1')
export class FnSir00101Controller {
  @Post('/integrations/execute')
  @HttpCode(200)
  async executeIntegration(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const data = checks.inputOf(req.body);
    const targetSystem = typeof data['targetSystem'] === 'string' ? data['targetSystem'].trim() : '';
    if (targetSystem === '' || targetSystem.length > 50) {
      throw new ApiError(400, 'VALIDATION_FAILED', '연계 대상을 입력해 주세요.');
    }
    const direction = data['direction'];
    if (typeof direction !== 'string' || !DIRECTIONS.includes(direction)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '연계 방향을 선택해 주세요.');
    }
    const interfaceName = optionalText(data['interfaceName'], 100, '연계 인터페이스 이름');
    const requestSummary = optionalText(data['requestSummary'], 100000, '연계 요청 데이터 요약');
    if (!ALLOWED_TARGETS.includes(targetSystem)) {
      throw new ApiError(422, 'INTEGRATION_SPEC_NOT_DEFINED', '연계 명세에 없는 연계 대상입니다.');
    }
    // 실패 이력을 남기기 위해 기록은 먼저 확정하고, 502는 트랜잭션 밖에서 던진다.
    const outcome = await transaction(async (db) => {
      const rows = await db.query(
        'INSERT INTO integration_log (target_system, direction, interface_name, result_status, failure_reason, occurred_at, request_summary, response_summary, created_at, updated_at) ' +
          'VALUES (:targetSystem, :direction, :interfaceName, :resultStatus, :failureReason, now(), :requestSummary, NULL, now(), now()) ' +
          'RETURNING result_status AS "resultStatus", failure_reason AS "failureReason"',
        {
          targetSystem: targetSystem,
          direction: direction,
          interfaceName: interfaceName,
          resultStatus: 'FAILURE',
          failureReason: NO_CONNECTOR_REASON,
          requestSummary: requestSummary,
        },
      );
      return rows[0];
    });
    throw new ApiError(502, 'EXTERNAL_SYSTEM_FAILED', String(outcome['failureReason']));
  }

  @Get('/integration-logs')
  async listIntegrationLogs(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const query = checks.queryOf(req.query);
    const page = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    const sizeRaw = query['size'] === undefined || query['size'] === '' ? 20 : Number(query['size']);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 크기가 올바르지 않습니다.');
    }
    const size = Math.min(sizeRaw, 200);
    const targetSystem = typeof query['targetSystem'] === 'string' && query['targetSystem'] !== '' ? query['targetSystem'] : null;
    const resultStatus = typeof query['resultStatus'] === 'string' && query['resultStatus'] !== '' ? query['resultStatus'] : null;
    if (resultStatus !== null && resultStatus !== 'SUCCESS' && resultStatus !== 'FAILURE') {
      throw new ApiError(400, 'VALIDATION_FAILED', '연계 결과 값이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const where =
        'WHERE (CAST(:targetSystem AS varchar) IS NULL OR target_system = CAST(:targetSystem AS varchar)) ' +
        'AND (CAST(:resultStatus AS varchar) IS NULL OR result_status = CAST(:resultStatus AS varchar))';
      const items = await db.query(
        'SELECT target_system AS "targetSystem", direction AS "direction", interface_name AS "interfaceName", ' +
          'result_status AS "resultStatus", failure_reason AS "failureReason", occurred_at AS "occurredAt" ' +
          'FROM integration_log ' +
          where +
          ' ORDER BY occurred_at DESC, integration_log_id DESC LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)',
        { targetSystem: targetSystem, resultStatus: resultStatus, size: size, offset: page * size },
      );
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM integration_log ' + where,
        { targetSystem: targetSystem, resultStatus: resultStatus },
      );
      return { items: items, page: page, size: size, total: Number(counts[0]['total']) };
    });
  }
}

