import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  Num,
  Pager,
  Pairs,
  Select,
  TextInput,
  Tiles,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const TARGETS: [string, string][] = [
  ['주거래은행 CMS', '주거래은행 CMS'],
  ['카드사', '카드사'],
  ['전자세금계산서', '전자세금계산서'],
  ['결의서', '결의서'],
];
const DIRECTIONS: [string, string][] = [
  ['SEND', '송신'],
  ['RECEIVE', '수신'],
];
const RESULTS: [string, string][] = [
  ['SUCCESS', '성공'],
  ['FAILURE', '실패'],
];
const SIZE = 20;

function directionName(value: unknown): string {
  return value === 'SEND' ? '송신' : value === 'RECEIVE' ? '수신' : '';
}

export default function FnSir00101Page({ role, notify }: PageProps) {
  const [targetSystem, setTargetSystem] = useState('');
  const [resultStatus, setResultStatus] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [executing, setExecuting] = useState(false);
  const [detail, setDetail] = useState<Row | null>(null);
  const [formTarget, setFormTarget] = useState('');
  const [formDirection, setFormDirection] = useState('');
  const [interfaceName, setInterfaceName] = useState('');
  const [requestSummary, setRequestSummary] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/integration-logs', role, undefined, { ...applied, page: page, size: SIZE }),
    [role, applied, page],
  );
  const rows = list.data ? list.data.items : [];
  const total = list.data ? list.data.total : 0;

  function search() {
    setPage(0);
    setApplied({ targetSystem: targetSystem, resultStatus: resultStatus });
  }

  function reset() {
    setTargetSystem('');
    setResultStatus('');
    setPage(0);
    setApplied({});
  }

  function openExecute() {
    setFormTarget('');
    setFormDirection('');
    setInterfaceName('');
    setRequestSummary('');
    setExecuting(true);
  }

  async function execute() {
    if (formTarget === '') {
      throw new Error('연계 대상을 선택해 주세요.');
    }
    if (formDirection === '') {
      throw new Error('연계 방향을 선택해 주세요.');
    }
    try {
      await call('POST', '/integrations/execute', role, {
        targetSystem: formTarget,
        direction: formDirection,
        interfaceName: interfaceName,
        requestSummary: requestSummary,
      });
    } finally {
      list.reload();
    }
    notify('연동을 실행했습니다.');
    setExecuting(false);
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>연계 이력</h2>
        <Tiles items={[['조회된 건수', <Num value={total} />]]} />
      </section>
      <section className="box span-8">
        <h2>연계 실행</h2>
        <Band>
          <button type="button" onClick={openExecute}>
            연동 실행
          </button>
        </Band>
      </section>
      <section className="box span-12">
        <h2>연계 결과 이력</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="연계 대상 시스템">
            <Select value={targetSystem} onChange={setTargetSystem} options={TARGETS} placeholder="전체" />
          </Field>
          <Field label="연계 결과">
            <Select value={resultStatus} onChange={setResultStatus} options={RESULTS} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={total} />
        <DataTable
          rows={rows}
          onRowClick={(row) => setDetail(row)}
          empty="연계 이력이 없습니다."
          columns={[
            { key: 'occurredAt', label: '연계 일시', render: (r) => <DateText value={r['occurredAt']} time /> },
            { key: 'targetSystem', label: '연계 대상 시스템' },
            { key: 'direction', label: '연계 방향', render: (r) => <span>{directionName(r['direction'])}</span> },
            { key: 'interfaceName', label: '연계 구분' },
            { key: 'resultStatus', label: '연계 결과', render: (r) => <Badge value={r['resultStatus']} /> },
            { key: 'failureReason', label: '실패 사유' },
          ]}
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
      {executing && (
        <Drawer title="외부 시스템 연동 실행" onClose={() => setExecuting(false)}>
          <Form onSubmit={execute} submit="실행">
            <Field label="연계 대상" required>
              <Select value={formTarget} onChange={setFormTarget} options={TARGETS} />
            </Field>
            <Field label="연계 방향" required>
              <Select value={formDirection} onChange={setFormDirection} options={DIRECTIONS} />
            </Field>
            <Field label="연계 인터페이스 이름">
              <TextInput value={interfaceName} onChange={setInterfaceName} />
            </Field>
            <Field label="연계 요청 데이터 요약" wide>
              <TextInput value={requestSummary} onChange={setRequestSummary} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
      {detail && (
        <Drawer title="연계 이력 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['연계 일시', <DateText value={detail['occurredAt']} time />],
              ['연계 대상 시스템', <span>{String(detail['targetSystem'] ?? '')}</span>],
              ['연계 방향', <span>{directionName(detail['direction'])}</span>],
              ['연계 구분', <span>{String(detail['interfaceName'] ?? '')}</span>],
              ['연계 결과', <Badge value={detail['resultStatus']} />],
              ['실패 사유', <span>{String(detail['failureReason'] ?? '')}</span>],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
